import Foundation
import NIO
import Crypto

// MARK: - Role System
enum Permission: UInt8, Comparable {
    case guest = 0
    case member = 1
    case moderator = 2
    case admin = 3
    case owner = 4

    static func < (lhs: Permission, rhs: Permission) -> Bool {
        return lhs.rawValue < rhs.rawValue
    }
}

// MARK: - Token Validation
struct TokenClaims {
    let userId: String
    let baseRole: Permission
    let issuedAt: Date
    let expiresAt: Date
    let scopes: Set<String>
}

class TokenValidator {
    private let secretKey: Data
    private var revokedTokens: Set<String> = []

    init(secretKey: Data) {
        self.secretKey = secretKey
    }

    // Base64URL decoding helper for JWT segments
    private func base64URLDecode(_ input: Substring) -> Data? {
        var base64 = String(input)
            .replacingOccurrences(of: "-", with: "+")
            .replacingOccurrences(of: "_", with: "/")
        let padding = (4 - base64.count % 4) % 4
        base64 += String(repeating: "=", count: padding)
        return Data(base64Encoded: base64)
    }

    // Verify the HMAC-SHA256 signature over "header.payload" using the secret key.
    private func verifySignature(header: Substring, payload: Substring, signature: Substring) -> Bool {
        guard let providedSignature = base64URLDecode(signature) else { return false }
        let signingInput = "\(header).\(payload)"
        guard let signingData = signingInput.data(using: .utf8) else { return false }

        let key = SymmetricKey(data: secretKey)
        let computed = HMAC<SHA256>.authenticationCode(for: signingData, using: key)
        let computedData = Data(computed)

        // Constant-time comparison to avoid timing side channels.
        guard computedData.count == providedSignature.count else { return false }
        var diff: UInt8 = 0
        for (a, b) in zip(computedData, providedSignature) {
            diff |= a ^ b
        }
        return diff == 0
    }

    func validate(token: String) throws -> TokenClaims {
        // Simplified JWT-like validation
        let parts = token.split(separator: ".")
        guard parts.count == 3 else { throw AuthError.malformedToken }

        guard !revokedTokens.contains(token) else { throw AuthError.revokedToken }

        // Verify signature BEFORE trusting any claims.
        guard verifySignature(header: parts[0], payload: parts[1], signature: parts[2]) else {
            throw AuthError.invalidSignature
        }

        // Decode claims (simplified)
        guard let claimsData = base64URLDecode(parts[1]),
              let claims = try? JSONSerialization.jsonObject(with: claimsData) as? [String: Any],
              let userId = claims["sub"] as? String,
              let roleValue = claims["role"] as? Int,
              let exp = claims["exp"] as? TimeInterval,
              let iat = claims["iat"] as? TimeInterval
        else { throw AuthError.invalidClaims }

        let expiresAt = Date(timeIntervalSince1970: exp)
        guard expiresAt > Date() else { throw AuthError.expiredToken }

        guard let role = Permission(rawValue: UInt8(clamping: roleValue)) else {
            throw AuthError.invalidRole
        }

        let scopes = (claims["scopes"] as? [String]).map(Set.init) ?? Set<String>()

        return TokenClaims(
            userId: userId,
            baseRole: role,
            issuedAt: Date(timeIntervalSince1970: iat),
            expiresAt: expiresAt,
            scopes: scopes
        )
    }

    func revoke(token: String) {
        revokedTokens.insert(token)
    }
}

// MARK: - Resource Access Control
struct Resource {
    let id: String
    let ownerId: String
    let requiredRole: Permission
    let isPublic: Bool
    let allowedScopes: Set<String>
}

struct AccessGrant {
    let userId: String
    let resourceId: String
    let grantedRole: Permission
    let conditions: [String: String]
}

// MARK: - Policy Engine
class PolicyEngine {
    private var resources: [String: Resource] = [:]
    private var accessGrants: [String: [AccessGrant]] = [:] // userId -> grants
    private var roleEscalationLog: [(userId: String, from: Permission, to: Permission, timestamp: Date)] = []

    func registerResource(_ resource: Resource) {
        resources[resource.id] = resource
    }

    func grantAccess(_ grant: AccessGrant) {
        accessGrants[grant.userId, default: []].append(grant)
    }

    /// Computes the effective permission level for a user on a specific resource.
    /// Takes into account: base role, access grants, resource ownership.
    func computeEffectivePermission(claims: TokenClaims, resourceId: String) -> Permission {
        var effectiveRole = claims.baseRole

        // Check if user is resource owner
        if let resource = resources[resourceId], resource.ownerId == claims.userId {
            effectiveRole = max(effectiveRole, .admin)
        }

        // Apply access grants
        if let grants = accessGrants[claims.userId] {
            for grant in grants where grant.resourceId == resourceId {
                effectiveRole = max(effectiveRole, grant.grantedRole)
            }
        }

        return effectiveRole
    }

    /// Determines the minimum required permission for an action on a resource.
    /// Returns nil if the resource doesn't exist.
    func requiredPermission(action: String, resourceId: String) -> Permission? {
        guard let resource = resources[resourceId] else { return nil }

        switch action {
        case "read":
            return resource.isPublic ? .guest : resource.requiredRole
        case "write", "update":
            return resource.requiredRole
        case "delete":
            return max(resource.requiredRole, .moderator)
        case "admin":
            return .admin
        case "transfer_ownership":
            return .owner
        default:
            return .admin // Unknown actions require admin
        }
    }

    /// Core authorization decision. Checks scope, role level, and temporal constraints.
    func authorize(claims: TokenClaims, action: String, resourceId: String) -> AuthDecision {
        // Step 1: Verify scope
        let requiredScope = "\(action):\(resourceId)"
        let wildcardScope = "\(action):*"
        let hasScope = claims.scopes.contains(requiredScope) || 
                       claims.scopes.contains(wildcardScope) ||
                       claims.scopes.contains("*")

        guard hasScope else {
            return .denied(reason: "Insufficient scope")
        }

        // Step 2: Get required permission
        guard let required = requiredPermission(action: action, resourceId: resourceId) else {
            return .denied(reason: "Resource not found")
        }

        // Step 3: Compute effective permission
        let effective = computeEffectivePermission(claims: claims, resourceId: resourceId)

        // Step 4: Role-based check with escalation detection
        let decision = checkRoleEscalation(claims: claims, effective: effective, required: required)

        return decision
    }

    /// Checks for role escalation attempts and enforces role hierarchy.
    /// Uses distance-based validation to prevent privilege jumps.
    private func checkRoleEscalation(claims: TokenClaims, effective: Permission, required: Permission) -> AuthDecision {
        // Calculate the "distance" between base role and effective role
        // to detect suspicious escalation patterns
        let escalationDistance = Int(effective.rawValue) - Int(claims.baseRole.rawValue)

        // If escalation distance exceeds 2 levels, require additional verification
        // This prevents a guest from jumping directly to admin via grants
        if escalationDistance > 2 {
            roleEscalationLog.append((claims.userId, claims.baseRole, effective, Date()))
            // Still allow but log - this is an audit mechanism, not a block
        }

        // Core permission check: effective role must meet or exceed required
        guard effective >= required else {
            return .denied(reason: "Insufficient permission level (have: \(effective), need: \(required))")
        }

        return .allowed
    }
}

// MARK: - Auth Decision
enum AuthDecision {
    case allowed
    case denied(reason: String)
}

enum AuthError: Error {
    case malformedToken
    case revokedToken
    case invalidClaims
    case expiredToken
    case invalidRole
    case invalidSignature
}

// MARK: - Request Handler
class SecureAPIHandler {
    private let tokenValidator: TokenValidator
    private let policyEngine: PolicyEngine

    init(tokenValidator: TokenValidator, policyEngine: PolicyEngine) {
        self.tokenValidator = tokenValidator
        self.policyEngine = policyEngine
    }

    func handleRequest(token: String, action: String, resourceId: String) -> (Int, String) {
        // Validate token
        let claims: TokenClaims
        do {
            claims = try tokenValidator.validate(token: token)
        } catch {
            return (401, "Authentication failed: \(error)")
        }

        // Authorize action
        let decision = policyEngine.authorize(claims: claims, action: action, resourceId: resourceId)

        switch decision {
        case .allowed:
            return (200, "Action '\(action)' on resource '\(resourceId)' authorized for user '\(claims.userId)'")
        case .denied(let reason):
            return (403, "Access denied: \(reason)")
        }
    }
}
